<template>
  <view class="netops-page infra-page">
    <view class="infra-hero"><view><text>INFRASTRUCTURE</text><strong>基础设施监控</strong><small>服务器资源、核心服务与数据组件健康状态</small></view><view class="health"><strong>{{ healthyRate }}%</strong><text>健康度</text></view></view>
    <view v-if="error" class="notice">{{ error }}</view>
    <view class="summary"><view><text>节点</text><strong>{{ data.nodes.length }}</strong></view><view><text>组件</text><strong>{{ data.summary.total_components || 0 }}</strong></view><view><text>异常组件</text><strong class="danger">{{ data.summary.failed_components || 0 }}</strong></view><view><text>关注节点</text><strong class="warn">{{ data.summary.warning_nodes || 0 }}</strong></view></view>
    <view v-if="loading" class="status-text">正在检查基础设施状态…</view>
    <view v-else class="node-list"><view v-for="node in data.nodes" :key="node.id" class="section-card node-card"><view class="node-head"><view class="node-icon">{{ node.id }}</view><view class="node-copy"><view><strong>{{ node.name || `节点 ${node.id}` }}</strong><StatusBadge :value="node.status" :text="statusLabel(node.status)" /></view><text>{{ node.role || '--' }} · {{ node.host || '--' }}</text><small>{{ observed(node) }}</small></view></view>
      <view class="resource-grid"><view><text>CPU</text><strong>{{ percent(resource(node,'cpu_percent')) }}</strong></view><view><text>内存</text><strong>{{ percent(resource(node,'memory').percent || resource(node,'memory_percent')) }}</strong></view><view><text>磁盘</text><strong>{{ percent(resource(node,'disk').percent || resource(node,'disk_percent')) }}</strong></view></view>
      <view class="service-list"><view v-for="service in node.services || []" :key="service.key" @tap="openLogs(node,service)"><i :class="tone(service.status)" /><view><strong>{{ service.label }}</strong><text>{{ service.detail || statusLabel(service.status) }}</text></view><text class="service-more">日志 ›</text></view></view>
    </view><EmptyState v-if="!data.nodes.length" mark="服" title="暂无基础设施数据" description="下拉刷新后仍无数据时，请检查探针配置。" /></view>
    <view class="section-card components"><view class="section-head"><view class="section-head-title">核心组件</view><view class="section-head-meta">{{ data.components.length }} 项</view></view><view class="component-grid"><view v-for="item in data.components" :key="`${item.node_id}-${item.key}`"><i :class="tone(item.status)" /><strong>{{ item.label }}</strong><text>{{ item.node_id }} · {{ item.node_name }}</text></view></view></view>
    <view v-if="selectedService" class="mask" @tap="closeLogs"><view class="log-sheet" @tap.stop><view class="sheet-head"><view><text>{{ selectedNode.name }}</text><strong>{{ selectedService.label }} · 服务日志</strong></view><view @tap="closeLogs">×</view></view><view v-if="logsLoading" class="status-text">正在读取日志…</view><scroll-view v-else scroll-y class="logs"><view v-if="logs.message" class="log-message">{{ logs.message }}</view><text v-for="(line,index) in logs.lines || []" :key="index">{{ line }}</text><EmptyState v-if="!(logs.lines || []).length && !logs.message" mark="志" title="暂无服务日志" /></scroll-view></view></view>
  </view>
</template>

<script setup>
import { computed, ref } from 'vue'
import { onLoad, onPullDownRefresh } from '@dcloudio/uni-app'
import EmptyState from '../../../components/netops/EmptyState.vue'
import StatusBadge from '../../../components/netops/StatusBadge.vue'
import { getInfrastructureLogs, getInfrastructureOverview } from '../../../api/netops'
import { messageLabel } from '../../../utils/labels'

const empty = { observed_at: '', nodes: [], components: [], topology: [], summary: {} }
const data = ref({ ...empty }); const loading = ref(false); const error = ref(''); const selectedNode = ref(null); const selectedService = ref(null); const logs = ref({ lines: [] }); const logsLoading = ref(false)
const healthyRate = computed(() => { const total = Number(data.value.summary.total_components || 0); const failed = Number(data.value.summary.failed_components || 0); return total ? Math.round((total - failed) * 100 / total) : 0 })
onLoad(() => load(false)); onPullDownRefresh(async () => { await load(true); uni.stopPullDownRefresh() })
async function load(refresh) { loading.value = !data.value.nodes.length; error.value = ''; try { data.value = await getInfrastructureOverview(refresh) } catch (err) { error.value = messageLabel(err.message) } finally { loading.value = false } }
function resource(node,key) { return (node.resources || {})[key] || {} } function percent(value) { const raw = typeof value === 'object' ? value.percent : value; const number = Number(raw); return Number.isFinite(number) ? `${number.toFixed(1)}%` : '--' }
function tone(value) { return value === 'ok' ? 'ok' : value === 'warning' ? 'warning' : 'failed' } function statusLabel(value) { return value === 'ok' ? '运行正常' : value === 'warning' ? '需关注' : '故障 / 不可达' }
function observed(node) { return node.observed_at ? `${node.observed_at}${node.response_ms != null ? ` · ${node.response_ms} ms` : ''}` : '暂未采集' }
async function openLogs(node,service) { selectedNode.value = node; selectedService.value = service; logs.value = { lines: [] }; if (node.id === '212') { logs.value = { message: '该节点当前使用只读指标检查，尚未部署主机日志探针。', lines: [] }; return } logsLoading.value = true; try { logs.value = await getInfrastructureLogs({ node_id: node.id, service: service.key, limit: 80 }) } catch (err) { logs.value = { message: messageLabel(err.message), lines: [] } } finally { logsLoading.value = false } }
function closeLogs() { selectedNode.value = null; selectedService.value = null; logs.value = { lines: [] } }
</script>

<style scoped>
.infra-page{padding-top:0}.infra-hero{display:flex;align-items:center;justify-content:space-between;margin:0 -24rpx 17rpx;padding:34rpx 30rpx;border-radius:0 0 28rpx 28rpx;background:linear-gradient(145deg,#123f49,#1d6d72);color:#fff}.infra-hero text,.infra-hero strong,.infra-hero small{display:block}.infra-hero>view:first-child>text{color:rgba(255,255,255,.52);font-size:17rpx;letter-spacing:2rpx}.infra-hero>view:first-child>strong{margin-top:7rpx;font-size:32rpx}.infra-hero small{margin-top:7rpx;color:rgba(255,255,255,.68);font-size:18rpx}.health{display:flex;width:76rpx;height:76rpx;flex:none;align-items:center;justify-content:center;border:1rpx solid rgba(255,255,255,.25);border-radius:50%;background:rgba(255,255,255,.1);text-align:center;flex-direction:column}.health strong{font-size:21rpx}.health text{font-size:14rpx;color:rgba(255,255,255,.65)}.notice{margin-bottom:15rpx;padding:15rpx 18rpx;border-radius:12rpx;background:#fdebea;color:#b34540;font-size:21rpx}.summary{display:grid;grid-template-columns:repeat(4,1fr);margin-bottom:17rpx;padding:16rpx 4rpx;border:1rpx solid #e1e7ee;border-radius:16rpx;background:#fff}.summary view{text-align:center}.summary text,.summary strong{display:block}.summary text{color:#8994a1;font-size:15rpx}.summary strong{margin-top:4rpx;color:#23666b;font-size:25rpx}.summary strong.danger{color:#ba4841}.summary strong.warn{color:#b6751d}.node-list{display:flex;flex-direction:column;gap:16rpx}.node-card{padding:21rpx}.node-head{display:flex;align-items:center;gap:15rpx}.node-icon{display:flex;width:58rpx;height:58rpx;flex:none;align-items:center;justify-content:center;border-radius:17rpx;background:#e5f1f1;color:#17666a;font-size:19rpx;font-weight:700}.node-copy{min-width:0;flex:1}.node-copy>view{display:flex;align-items:center;justify-content:space-between;gap:12rpx}.node-copy strong{color:#2b3c4f;font-size:24rpx}.node-copy>text,.node-copy small{display:block;margin-top:4rpx;color:#7f8c9a;font-size:18rpx}.node-copy small{color:#9aa3ad;font-size:16rpx}.resource-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:9rpx;margin-top:16rpx}.resource-grid view{padding:12rpx;border-radius:11rpx;background:#f4f7f9;text-align:center}.resource-grid text,.resource-grid strong{display:block}.resource-grid text{color:#8c97a3;font-size:16rpx}.resource-grid strong{margin-top:4rpx;color:#36576f;font-size:22rpx}.service-list{margin-top:14rpx;border-top:1rpx solid #edf1f5}.service-list>view{display:flex;align-items:center;gap:12rpx;padding:14rpx 0;border-bottom:1rpx solid #f0f3f6}.service-list>view:last-child{border:0}.service-list i,.component-grid i{width:12rpx;height:12rpx;flex:none;border-radius:50%;background:#c74841}.service-list i.ok,.component-grid i.ok{background:#2db875}.service-list i.warning,.component-grid i.warning{background:#dfa039}.service-list>view>view{min-width:0;flex:1}.service-list strong,.service-list text{display:block}.service-list strong{color:#435469;font-size:20rpx}.service-list text{margin-top:3rpx;overflow:hidden;color:#8b96a3;font-size:16rpx;text-overflow:ellipsis;white-space:nowrap}.service-more{flex:none;color:#267078!important}.components{margin-top:17rpx}.component-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10rpx;padding:16rpx}.component-grid view{position:relative;padding:13rpx 13rpx 13rpx 31rpx;border-radius:11rpx;background:#f5f7f9}.component-grid i{position:absolute;top:19rpx;left:12rpx}.component-grid strong,.component-grid text{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.component-grid strong{color:#3b4c60;font-size:18rpx}.component-grid text{margin-top:4rpx;color:#929da8;font-size:15rpx}.mask{position:fixed;z-index:60;inset:0;display:flex;align-items:flex-end;background:rgba(20,25,38,.52)}.log-sheet{width:100%;height:76vh;border-radius:27rpx 27rpx 0 0;background:#f4f6f9}.sheet-head{display:flex;align-items:flex-start;justify-content:space-between;padding:24rpx;border-bottom:1rpx solid #e2e7ed;border-radius:27rpx 27rpx 0 0;background:#fff}.sheet-head text,.sheet-head strong{display:block}.sheet-head text{color:#277077;font-size:18rpx}.sheet-head strong{margin-top:5rpx;color:#293a4d;font-size:25rpx}.sheet-head>view:last-child{padding:0 8rpx;color:#7d8895;font-size:42rpx}.logs{height:calc(76vh - 112rpx);padding:18rpx 21rpx 38rpx;background:#17212c;box-sizing:border-box}.logs>text{display:block;color:#c9d5e0;font-family:monospace;font-size:17rpx;line-height:1.65;white-space:pre-wrap}.log-message{margin-bottom:14rpx;padding:14rpx;border-radius:10rpx;background:#283747;color:#dce5ed;font-size:19rpx;line-height:1.5}
</style>
